(6549068, 974148, 101668, '<td valign="top">Looks delicious</td>', 'Looks delicious', '2011-09-23 12:54:49.000000', NULL, 1),
(6549074, 974053, 101668, '<td valign="top">Nice enough picture but something bothers me. focus or lighting. Cant be too sure.</td>', 'Nice enough picture but something bothers me. focus or lighting. Cant be too sure.', '2011-09-23 13:00:13.000000', NULL, 1),
(6549077, 974081, 101668, '<td valign="top">Lovely colours and abstract.</td>', 'Lovely colours and abstract.', '2011-09-23 13:00:49.000000', NULL, 1),
(6549080, 973956, 101668, '<td valign="top">One thing is for sure. It is difficult to photograph glass. This is striking and love the lighting. Focus seems to be soft but not oof</td>', 'One thing is for sure. It is difficult to photograph glass. This is striking and love the lighting. Focus seems to be soft but not oof', '2011-09-23 13:03:38.000000', NULL, 1),
