(6549083, 973779, 101668, '<td valign="top">I am always in awe with something like this because I dont know how to do it. The wine is very red, isn''t it?</td>', 'I am always in awe with something like this because I dont know how to do it. The wine is very red, isn''t it?', '2011-09-23 13:05:48.000000', NULL, 1),
(6549087, 973943, 101668, '<td valign="top">Interesting point of view. Not my favourite photograph but technically good</td>', 'Interesting point of view. Not my favourite photograph but technically good', '2011-09-23 13:06:49.000000', NULL, 1),
(6549088, 973714, 101668, '<td valign="top">This is wonderful Beautiful photography</td>', 'This is wonderful Beautiful photography', '2011-09-23 13:07:40.000000', NULL, 1),
