(6549092, 973527, 101668, '<td valign="top">Swet idea much work and good photograph.</td>', 'Swet idea much work and good photograph.', '2011-09-23 13:10:47.000000', NULL, 1),
(6549098, 973860, 101668, '<td valign="top">Nice idea, not my favourite photograph,  though. Maybe its too busy I''m not sure. One thing I do know is that Cabertnet Sauvignon is a top wine.</td>', 'Nice idea, not my favourite photograph,  though. Maybe its too busy I''m not sure. One thing I do know is that Cabertnet Sauvignon is a top wine.', '2011-09-23 13:17:03.000000', NULL, 1),
(6549103, 973873, 101668, '<td valign="top">There is nothing striking in the picture. Leaves with the Eifel tower in the distance,</td>', 'There is nothing striking in the picture. Leaves with the Eifel tower in the distance,', '2011-09-23 13:19:31.000000', NULL, 1),
