(6549271, 974063, 138667, '<td valign="top">s</td>', 's', '2011-09-23 17:38:02.000000', NULL, 1),
(6549295, 973777, 59796, '<td valign="top">Very nice concept! Good soft lighting as well. I would''ve preferred a centered crop instead of the extra negative space on the right, but it''s not that big a deal - the concept is what stood out and wowed me.</td>', 'Very nice concept! Good soft lighting as well. I would''ve preferred a centered crop instead of the extra negative space on the right, but it''s not that big a deal - the concept is what stood out and wowed me.', '2011-09-23 18:10:49.000000', NULL, 1),
(6549296, 973633, 59796, '<td valign="top">For some reason even the water, that the bottle is floating in, is looking like wine to me :) Good concept - unique in this challenge. Could''ve used more light and definition on the head of the bottle itself though.</td>', 'For some reason even the water, that the bottle is floating in, is looking like wine to me :) Good concept - unique in this challenge. Could''ve used more light and definition on the head of the bottle itself though.', '2011-09-23 18:12:27.000000', NULL, 1),
(6549302, 973882, 59796, '<td valign="top">Love the smooth water and the stillness of the wine glass/bottle in contrast. The lighting, unfortunately, is quite harsh and unappealing to me :(</td>', 'Love the smooth water and the stillness of the wine glass/bottle in contrast. The lighting, unfortunately, is quite harsh and unappealing to me :(', '2011-09-23 18:17:38.000000', NULL, 1),
(6549305, 974137, 59796, '<td valign="top">I''ll pass on the corks thank you :)<br/>Interesting lines on the table cloth and at odds with those on the spoon.<br/>Love the lines reflections in the wine glass. A little more milk in the bowl would''ve added to the incongruence of the shot. The border would''ve been nice if the bowl weren''t cut off at the bottom I think.</td>', 'I''ll pass on the corks thank you :)Interesting lines on the table cloth and at odds with those on the spoon.Love the lines reflections in the wine glass. A little more milk in the bowl would''ve added to the incongruence of the shot. The border would''ve been nice if the bowl weren''t cut off at the bottom I think.', '2011-09-23 18:21:11.000000', NULL, 1),
(6549309, 973941, 59796, '<td valign="top">Great title! Love the selective color treatment and the intended softness.<br/>Not a fan of the harsh lighting at all though :(</td>', 'Great title! Love the selective color treatment and the intended softness.Not a fan of the harsh lighting at all though :(', '2011-09-23 18:22:54.000000', NULL, 1),
(6549314, 973999, 59796, '<td valign="top">A wine cellar is not a place many get to see. Very nice.<br/>If the picture were a little underexposed (to give more prominence to the candle) and if the white balance was set to daylight (to give a yellow cast to the entire place), it might''ve looked better (or atleast matched the title better) I think.</td>', 'A wine cellar is not a place many get to see. Very nice.If the picture were a little underexposed (to give more prominence to the candle) and if the white balance was set to daylight (to give a yellow cast to the entire place), it might''ve looked better (or atleast matched the title better) I think.', '2011-09-23 18:26:39.000000', NULL, 1),
(6549322, 974069, 59796, '<td valign="top">Nice vineyard. The contrast of the spring green with the dried up hills and soil is amazing! The clouds are amazing as well, but the sky treatment is very artificial and doesn''t gel with the rest of the picture.</td>', 'Nice vineyard. The contrast of the spring green with the dried up hills and soil is amazing! The clouds are amazing as well, but the sky treatment is very artificial and doesn''t gel with the rest of the picture.', '2011-09-23 18:37:23.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6549323, 974059, 138683, '<td valign="top">very nice use of light</td>', 'very nice use of light', '2011-09-23 18:39:04.000000', NULL, 1),
(6549325, 973527, 59796, '<td valign="top">Simple shot and Neat pattern :) <br/>I take it you collect corks? I only recognize Clos Du Bois (liked their chardonnay), and BV (liked their Cabernet).</td>', 'Simple shot and Neat pattern :) I take it you collect corks? I only recognize Clos Du Bois (liked their chardonnay), and BV (liked their Cabernet).', '2011-09-23 18:40:46.000000', NULL, 1),
(6549327, 973632, 59796, '<td valign="top">Love the low key minimalism and the subtle colors. Nicely done.</td>', 'Love the low key minimalism and the subtle colors. Nicely done.', '2011-09-23 18:42:49.000000', NULL, 1),
(6549330, 974149, 59796, '<td valign="top">Nice red back lighting.<br/>This shot would''ve been great but for a couple of things (just my opinion):<br/>1. The horizon is tilted - the table edge is not horizontal and wine bottle edge is not vertical. This is very distracting.<br/>2. The white reflection on the bottle and the glass. It''s competing with the back light for attention, and is at odds with the warm color everywhere else.</td>', 'Nice red back lighting.This shot would''ve been great but for a couple of things (just my opinion):1. The horizon is tilted - the table edge is not horizontal and wine bottle edge is not vertical. This is very distracting.2. The white reflection on the bottle and the glass. It''s competing with the back light for attention, and is at odds with the warm color everywhere else.', '2011-09-23 18:45:48.000000', NULL, 1),
(6549346, 974117, 138683, '<td valign="top">I believe photos are to be captured not created, this is my favorite</td>', 'I believe photos are to be captured not created, this is my favorite', '2011-09-23 19:01:02.000000', NULL, 1),
(6549349, 973858, 138683, '<td valign="top">very nice lighting</td>', 'very nice lighting', '2011-09-23 19:02:45.000000', NULL, 1),
